+const listAndSettle = async (url: string): Promise<Frame[]> => {
+  const client = open(url);
+  const frames: Frame[] = [];
+  await new Promise<void>(resolve => {
+    client.on('message', raw => {
+      const frame = JSON.parse(String(raw)) as Frame;
+      frames.push(frame);
+      if (frame.type === 'connected') client.send(JSON.stringify({type: 'list_conversations'}));
+      if (frame.type === 'conversation_list') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
+      if (frame.type === 'pong') resolve();
+    });
+  });
+  return frames;
+};
